export type Locale = "es" | "pt" | "en";

export type Localized = Record<Locale, string>;

export const t = (es: string, pt: string, en: string): Localized => ({ es, pt, en });

export type Lesson = {
  id: string;
  title: Localized;
  duration: number;
  objectives: Localized;
  concept: Localized;
  why: Localized;
  workflow: Localized;
  example: Localized;
  mistake: Localized;
  exercise: Localized;
  professionalUse: Localized;
};

export type QuizQuestion = {
  prompt: Localized;
  options: Localized[];
  correctIndex: number;
  rationale: Localized;
};

export type CourseModule = {
  id: string;
  order: number;
  level: Localized;
  title: Localized;
  summary: Localized;
  competencies: Localized[];
  caseStudy: Localized;
  guidedPractice: Localized;
  individualPractice: Localized;
  miniProject: Localized;
  rubricFocus: Localized[];
  glossary: Array<{ term: string; definition: Localized }>;
  lessons: Lesson[];
  quiz: QuizQuestion[];
};

const lesson = (
  id: string,
  title: Localized,
  concept: Localized,
  why: Localized,
  workflow: Localized,
  example: Localized,
  mistake: Localized,
  exercise: Localized,
  professionalUse: Localized,
  duration = 34,
): Lesson => ({
  id,
  title,
  duration,
  objectives: t(
    `Al finalizar, podrás explicar ${title.es.toLowerCase()}, aplicarlo a una decisión de diseño y justificar tu razonamiento con una evidencia o artefacto observable.`,
    `Ao finalizar, você poderá explicar ${title.pt.toLowerCase()}, aplicá-lo a uma decisão de design e justificar seu raciocínio com uma evidência ou artefato observável.`,
    `By the end, you can explain ${title.en.toLowerCase()}, apply it to a design decision, and justify your reasoning with observable evidence or an artifact.`,
  ),
  concept,
  why,
  workflow,
  example,
  mistake,
  exercise,
  professionalUse,
});

const q = (prompt: Localized, options: Localized[], correctIndex: number, rationale: Localized): QuizQuestion => ({ prompt, options, correctIndex, rationale });

